-- ════════════════════════════════════════════════════════════════════
-- Sprint 14 — Block Modeler (MVP)
-- ────────────────────────────────────────────────────────────────────
-- Replaces the data paths behind ProgressionMatrix, ProgressionSuggestions
-- and VolumeDesigner with: canonical Week 1 (existing plan_sessions) +
-- shape (training_blocks) → generated weeks (plan_sessions, is_generated).
--
-- • Additive + idempotent. Safe to re-run. No drops, no data loss.
-- • block_sessions (0 rows in prod) is deprecated, not dropped.
-- • Library tables are read-only for coaches; engine (programEngine.ts)
--   is the source of truth for math — formulas here are documentation.
-- Generated by scripts/buildSeed.ts — edit weekTemplates.ts, not the INSERTs.
-- ════════════════════════════════════════════════════════════════════
begin;

-- ─── 1. Library: load shapes ────────────────────────────────────────
create table if not exists public.load_shapes (
  slug            text primary key,
  name            text not null,
  coach_line      text not null,
  best_for        text[] not null default '{}',
  default_deload  text not null default 'every_4'
                  check (default_deload in ('none','every_3','every_4','final')),
  formula         jsonb not null,          -- documents programEngine.SHAPES[slug]
  sort_order      int  not null default 0,
  is_active       boolean not null default true
);

insert into public.load_shapes (slug, name, coach_line, best_for, default_deload, formula, sort_order) values
 ('steady_build','Steady build','Volume holds, intensity climbs a step each week. The classic.',
   array['strength','general','novice'],'every_4',
   '{"volume":"1 + 0.025b","intensity_steps":"b"}',1),
 ('accumulate','Accumulate','Volume climbs, intensity holds. GPP, hypertrophy, work capacity.',
   array['gpp','hypertrophy','endurance base','tempo'],'every_4',
   '{"volume":"min(1.4, 1 + 0.08b)","intensity_steps":"0"}',2),
 ('intensify','Intensify','Volume comes down as intensity goes up. SPP, strength, speed.',
   array['spp','max strength','speed'],'every_4',
   '{"volume":"max(0.6, 1 - 0.1b)","intensity_steps":"b"}',3),
 ('peak','Peak','Sharpen, then cut volume hard in the final weeks. Competition.',
   array['competition','taper','testing'],'none',
   '{"volume":"max(0.7, 1 - 0.05b); final third tapers -20%/wk (floor 0.4)","intensity_steps":"b, held through taper"}',4),
 ('maintain','Maintain','Same work every week. In-season — keep what you built.',
   array['in-season','maintenance'],'none',
   '{"volume":"1","intensity_steps":"0"}',5)
on conflict (slug) do update set
  name = excluded.name, coach_line = excluded.coach_line, best_for = excluded.best_for,
  default_deload = excluded.default_deload, formula = excluded.formula, sort_order = excluded.sort_order;

-- ─── 2. Library: progression levers ─────────────────────────────────
-- Active = shipped in programEngine.ts. Inactive = Version B roadmap (seeded so
-- the UI/AI vocabulary is stable from day one).
create table if not exists public.progression_levers (
  slug          text primary key,
  name          text not null,
  coach_line    text not null,
  applies_to    text[] not null default '{}',
  default_step  numeric,
  step_unit     text,
  sort_order    int not null default 0,
  is_active     boolean not null default true
);

insert into public.progression_levers (slug, name, coach_line, applies_to, default_step, step_unit, sort_order, is_active) values
 ('hold','Nothing','Stays exactly as Week 1. Warm-ups, drills, mobility, technique.', array['warm_up','mobility','drill','technique'],0,null,1,true),
 ('load','Load','Gets heavier with the week''s intensity; sets follow the week''s volume.', array['compound_lift','isolation'],2.5,'%1RM pts (kg if no %; +0.5 RPE)',2,true),
 ('volume','Volume','More (or fewer) reps, sets or meters with the week''s volume. Speed stays.', array['sprint','plyometric','conditioning'],0,'% pts (default holds intensity)',3,true),
 ('reps','Reps','Climbs the rep range one rep per build week, then resets on deload.', array['isolation','compound_lift'],1,'reps',4,true),
 ('distance','Distance','Short-to-long: rep distance grows each build week.', array['sprint'],10,'m',5,true),
 ('ladder','Custom ladder','Your own week-by-week table (e.g. 5s/3s/1s/deload). Repeats.', array['compound_lift'],null,null,6,true),
 ('rpe_target','RPE target','Prescribe effort, athlete picks the load. Engine suggests load from logs.', array['compound_lift'],0.5,'RPE',7,false),
 ('density','Density','Same work, less rest.', array['conditioning','isolation'],-10,'s rest',8,false),
 ('velocity','Velocity','Load set by bar-speed target (VBT).', array['compound_lift'],null,'m/s',9,false),
 ('time','Time','Duration-based work grows or shrinks with volume.', array['conditioning','mobility'],null,'s',10,false)
on conflict (slug) do update set
  name = excluded.name, coach_line = excluded.coach_line, applies_to = excluded.applies_to,
  default_step = excluded.default_step, step_unit = excluded.step_unit,
  sort_order = excluded.sort_order, is_active = excluded.is_active;

-- Library RLS: everyone signed in can read; nobody writes from the client.
alter table public.load_shapes enable row level security;
alter table public.progression_levers enable row level security;
drop policy if exists load_shapes_read on public.load_shapes;
create policy load_shapes_read on public.load_shapes for select to authenticated using (true);
drop policy if exists progression_levers_read on public.progression_levers;
create policy progression_levers_read on public.progression_levers for select to authenticated using (true);

-- ─── 3. Library: canonical-week templates ───────────────────────────
create table if not exists public.week_templates (
  id                     uuid primary key default gen_random_uuid(),
  slug                   text unique,
  coach_id               uuid references public.profiles(id) on delete cascade,  -- null = system
  name                   text not null,
  coach_line             text,
  sport_tags             text[] not null default '{}',
  methodology_short_name text,             -- soft link to methodology_profiles.short_name
  level                  text check (level in ('beginner','intermediate','advanced','elite')),
  shape                  text not null default 'steady_build' references public.load_shapes(slug),
  deload                 text not null default 'every_4'
                         check (deload in ('none','every_3','every_4','final')),
  weeks                  int  not null default 6 check (weeks between 2 and 12),
  days                   jsonb not null,   -- engine Session[]: [{day_of_week, session_name, exercises:[…]}]
  is_public              boolean not null default false,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
create index if not exists idx_week_templates_coach on public.week_templates(coach_id);

alter table public.week_templates enable row level security;
-- One-way policies only (no joins back to other RLS tables → no recursion).
drop policy if exists week_templates_read on public.week_templates;
create policy week_templates_read on public.week_templates for select to authenticated
  using (coach_id is null or is_public or coach_id = auth.uid());
drop policy if exists week_templates_write on public.week_templates;
create policy week_templates_write on public.week_templates for all to authenticated
  using (coach_id = auth.uid()) with check (coach_id = auth.uid());

-- ─── 4. training_blocks: shape config ───────────────────────────────
-- progression_pattern now holds a load_shapes.slug (soft FK — legacy values tolerated).
alter table public.training_blocks
  add column if not exists deload_cadence text not null default 'every_4',
  add column if not exists week_overrides jsonb not null default '{}'::jsonb,  -- {"3":{"volume":1.2}}
  add column if not exists modeled_at timestamptz;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'training_blocks_deload_cadence_check') then
    alter table public.training_blocks add constraint training_blocks_deload_cadence_check
      check (deload_cadence in ('none','every_3','every_4','final'));
  end if;
end $$;

-- Carry Sprint 13.6 VolumeDesigner presets across (mirrors LEGACY_SHAPE_MAP in the engine).
update public.training_blocks tb set
  progression_pattern = m.shape,
  deload_cadence      = m.deload
from (values
  ('linear_ramp','accumulate','none'), ('wave_3_1','steady_build','every_4'),
  ('wave_2_1','steady_build','every_3'), ('step_load','steady_build','every_4'),
  ('reverse_taper','peak','none'), ('front_loaded','intensify','none')
) as m(legacy, shape, deload)
where tb.progression_params->>'preset_shape' = m.legacy
  and (tb.progression_pattern is null or tb.progression_pattern not in (select slug from public.load_shapes));

-- ─── 5. block_weeks: taper + pin flags ──────────────────────────────
-- volume_modifier / intensity_modifier / is_deload already exist and now hold
-- the engine's WeekTarget.volume / .intensity / .isDeload.
alter table public.block_weeks
  add column if not exists is_taper  boolean not null default false,
  add column if not exists is_pinned boolean not null default false;

-- ─── 6. plan_sessions: provenance ───────────────────────────────────
alter table public.plan_sessions
  add column if not exists is_generated boolean not null default false,
  add column if not exists canonical_session_id uuid references public.plan_sessions(id) on delete set null;
create index if not exists idx_plan_sessions_canonical on public.plan_sessions(canonical_session_id);
-- Per-exercise pins live inside session_data: { …, "pinned": true, "canonical_ref": "0:2" }

-- ─── 7. exercise_library.load_type ──────────────────────────────────
-- Tells the engine/UI what "volume" means for an exercise. Backfill is conservative;
-- coaches can correct in the library later.
alter table public.exercise_library add column if not exists load_type text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_load_type_check') then
    alter table public.exercise_library add constraint exercise_library_load_type_check
      check (load_type is null or load_type in ('external_load','bodyweight','distance','time','contacts','none'));
  end if;
end $$;

update public.exercise_library set load_type = case
    when category in ('warmup','cooldown') then 'none'
    when category = 'plyometric' and name ilike any (array['%slam%','%throw%','%push-up%']) then 'external_load'
    when category = 'plyometric' then 'contacts'
    when name ilike any (array['%sprint%','%falling start%','%block start%','%tempo%','%run%','%strides%']) then 'distance'
    when name ilike any (array['%battle rope%','%plank%','%hang%','%carry%']) then 'time'
    when name ilike any (array['%medicine ball%','%med ball%','%kettlebell%']) then 'external_load'
    when category = 'drill' and movement_pattern = 'locomotion' then 'none'
    when name ilike any (array['%chin-up%','%pull-up%','%push-up%','%dip%','%bird dog%','%ab wheel%',
                               '%inverted row%','%back extension%','%nordic%','%copenhagen%']) then 'bodyweight'
    when category in ('primary','accessory') or movement_pattern = 'skill' then 'external_load'
    else 'none' end
where load_type is null;

-- ─── 8. Make the 13 system season templates shape-aware ─────────────
-- Adds {"shape","deload"} to every block so a season template can be modeled
-- block-by-block. Vocabulary verified against production structure->blocks.
update public.periodization_templates p
set structure = jsonb_set(p.structure, '{blocks}', (
  select jsonb_agg(b || jsonb_build_object(
    'shape', case
      when b->>'type' = 'competition' and b->>'intensity' in ('peak','high') then 'peak'
      when b->>'type' in ('competition','deload') then 'maintain'
      when b->>'volume' = 'low' and b->>'intensity' = 'moderate' then 'maintain'
      when b->>'volume' = 'high' and b->>'intensity' = 'high' then 'steady_build'
      when b->>'intensity' = 'high' then 'intensify'
      when b->>'volume' = 'high' or b->>'intensity' = 'low' then 'accumulate'
      else 'steady_build' end,
    'deload', case when b->>'type' in ('competition','deload')
                     or (b->>'volume' = 'low' and b->>'intensity' = 'moderate') then 'none' else 'every_4' end,
    'is_deload_block', b->>'type' = 'deload'
  ) order by ord)
  from jsonb_array_elements(p.structure->'blocks') with ordinality as x(b, ord)
))
where p.coach_id is null
  and jsonb_typeof(p.structure->'blocks') = 'array'
  and not (p.structure->'blocks'->0 ? 'shape');

-- ─── 9. Deprecations (no drops) ─────────────────────────────────────
comment on table public.block_sessions is
  'DEPRECATED Sprint 14 — never populated in prod. Canonical week = Week 1 plan_sessions. Drop after beta.';
comment on column public.training_blocks.progression_params is
  'LEGACY Sprint 13.6 (absolute tonnage targets). Superseded by progression_pattern + deload_cadence + week_overrides.';

